_SIZE_UNITS={'b','k','kb','kib','m','mb','mib','g','gb','gib','t','tb','tib','p','pb','pib'}
def _size_error(expr):
    text=expr.strip()
    text=re.sub(r'^(?:>=|<=|>|<|=)\s*','',text)
    parts=text.split('..',1) if '..' in text else [text]
    for part in parts:
        part=part.strip()
        if not part: continue
        if re.fullmatch(r'\d+(?:\.\d+)?\s*[A-Za-z]*',part):
            unit=re.search(r'([A-Za-z]+)\s*$',part)
            if not unit or unit.group(1).lower() in _SIZE_UNITS:
                continue
            else:
                return f"Unknown size suffix '{unit.group(1)}' (use B, K, M, G, T, P, KiB, MiB, ...)"
        return f"Missing numeric value in size literal '{part}'"
    return f"Missing numeric value in size literal '{expr}'"

def _time_error(expr):
    text=expr.strip()
    text=re.sub(r'^(?:>=|<=|>|<)\s*','',text)
    parts=text.split('..',1) if '..' in text else [text]
    for part in parts:
        part=part.strip()
        if not part: continue
        unit=re.fullmatch(r'(\d+(?:\.\d+)?)([A-Za-z]+)',part)
        if unit and unit.group(2).lower() not in {'s','m','h','d','w'}:
            return f"Unknown duration unit '{unit.group(2)}' in '{part}'"
        if re.match(r'^\d{4}-\d{2}-\d{2}',part):
            return f"Invalid duration literal '{part}'"
        return f"Unable to parse date/time '{part}'"
    return f"Unable to parse date/time '{expr}'"

def validate_ranges(a):
